pub fn dispatch_entity_piece_move(
    repo: &mut impl crate::kernel::Repository<Game>, parent_id: &str, element_id: &str, element_wants: &str, args: PieceMoveEntityArgs,
    mutations: &mut Vec<crate::kernel::MutationRecord>, owner_deref: Vec<(&'static str, crate::kernel::DerefNode)>, command_deref: Vec<(&'static str, crate::kernel::DerefNode)>,
) -> crate::kernel::DispatchResult<Game> {
        args.id.check_invariants()?;
        args.destination.check_invariants()?;
    let with_references = crate::kernel::WithReferences { command_deref: &command_deref, args: &args, owner_deref: &owner_deref };
    let seed_projections = crate::kernel::seeded_projections(&with_references, GAME_PROJECTED_FIELDS);

    crate::kernel::dispatch_entity(
        repo,
        parent_id,
        |r: &Game| &r.pieces,
        |r: &mut Game| &mut r.pieces,
        |el: &Piece| el.identity() == element_id,
        "Move",
        "Chess::Game",
        "Game",
        "label.value",
        "Piece",
        "id.value",
        element_wants,
        &with_references,
        &[
            crate::kernel::GivenSpec { description: "only an active game may be played", expr: Expr::Or(Box::new(Expr::Compare { op: crate::kernel::Comparison { less_than: false, equal: true, negated: false }, left: Box::new(Expr::Lookup("parent.status")), right: Box::new(Expr::Str("in_progress".to_string())) }), Box::new(Expr::Compare { op: crate::kernel::Comparison { less_than: false, equal: true, negated: false }, left: Box::new(Expr::Lookup("parent.status")), right: Box::new(Expr::Str("check".to_string())) })), corrects_event: None },
            crate::kernel::GivenSpec { description: "only the color to move may move a piece", expr: Expr::Compare { op: crate::kernel::Comparison { less_than: false, equal: true, negated: false }, left: Box::new(Expr::Lookup("parent.turn.value")), right: Box::new(Expr::Lookup("by.value")) }, corrects_event: None },
            crate::kernel::GivenSpec { description: "a piece may only be moved by its own color", expr: Expr::Compare { op: crate::kernel::Comparison { less_than: false, equal: true, negated: false }, left: Box::new(Expr::Lookup("by.value")), right: Box::new(Expr::Lookup("color.value")) }, corrects_event: None },
            crate::kernel::GivenSpec { description: "the destination differs from the current square", expr: Expr::Or(Box::new(Expr::Compare { op: crate::kernel::Comparison { less_than: false, equal: true, negated: true }, left: Box::new(Expr::Lookup("square.file")), right: Box::new(Expr::Lookup("destination.file")) }), Box::new(Expr::Compare { op: crate::kernel::Comparison { less_than: false, equal: true, negated: true }, left: Box::new(Expr::Lookup("square.rank")), right: Box::new(Expr::Lookup("destination.rank")) })), corrects_event: None },
            crate::kernel::GivenSpec { description: "no piece of the same color already stands on the destination", expr: Expr::BlockPredicate { mode: crate::kernel::BlockMode::None, receiver: Box::new(Expr::Lookup("parent.pieces")), param: "p", predicate: Box::new(Expr::And(Box::new(Expr::Compare { op: crate::kernel::Comparison { less_than: false, equal: true, negated: false }, left: Box::new(Expr::Lookup("p.status")), right: Box::new(Expr::Str("on_board".to_string())) }), Box::new(Expr::And(Box::new(Expr::Compare { op: crate::kernel::Comparison { less_than: false, equal: true, negated: false }, left: Box::new(Expr::Lookup("p.color.value")), right: Box::new(Expr::Lookup("color.value")) }), Box::new(Expr::And(Box::new(Expr::Compare { op: crate::kernel::Comparison { less_than: false, equal: true, negated: false }, left: Box::new(Expr::Lookup("p.square.file")), right: Box::new(Expr::Lookup("destination.file")) }), Box::new(Expr::Compare { op: crate::kernel::Comparison { less_than: false, equal: true, negated: false }, left: Box::new(Expr::Lookup("p.square.rank")), right: Box::new(Expr::Lookup("destination.rank")) }))))))) }, corrects_event: None },
        ],
        Some(crate::kernel::TransitionCheck { field: "status", from_states: &["on_board"] }),
        |record| {
        record.square = args.destination.clone();
        record.moved = MovedFlag::Moved;
            Ok(())
        },
        &[
            crate::kernel::EnsuresSpec { description: "the piece is exactly where it was told to move", expr: Expr::And(Box::new(Expr::Compare { op: crate::kernel::Comparison { less_than: false, equal: true, negated: false }, left: Box::new(Expr::Lookup("square.file")), right: Box::new(Expr::Lookup("destination.file")) }), Box::new(Expr::Compare { op: crate::kernel::Comparison { less_than: false, equal: true, negated: false }, left: Box::new(Expr::Lookup("square.rank")), right: Box::new(Expr::Lookup("destination.rank")) })) },
        ],
        &game_invariants(),
        &["PieceMoved"],
        args.to_json(),
        mutations,
        seed_projections,
    )
}

